/// 需要**从 JS 调用**的命令清单。
///
/// 这份清单是手写的（不是扫 `generate_handler!` 得来的），`tauri_plugin::Builder`
/// 会为每一项生成 `permissions/autogenerated/commands/<name>.toml`，提供
/// `allow-<name-with-dashes>` 权限。
///
/// ⚠️ 新增 @Command 且前端会 `invoke` 它时，**两处都要改**：
/// 1. 这里 —— 否则 `generate_context!` 直接编译失败，报
///    `SetPermissionNotFound { permission: "allow-xxx", set: "default" }`
/// 2. `permissions/default.toml` —— 否则编译能过，但运行时被 ACL 拒掉
///
/// 只由 Rust 侧调用的命令（如 `capture_screen`，走 `capture_screen_bytes`
/// 注入槽）**不用**列进来，它们不经过 ACL。
const COMMANDS: &[&str] = &[
    "is_supported",
    "check_permission",
    "request_permission",
    "show",
    "hide",
    "move_pet",
    "set_touchable",
    "set_expanded",
    "set_size",
    "set_scale",
    "is_visible",
    "status",
    "is_screen_capture_ready",
    "request_screen_capture",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS)
        .android_path("android")
        .build();
}
